const event = $json;
const validWorkflowId = (value) =>
  typeof value === 'string' && /^[A-Za-z0-9_-]{1,32}$/.test(value) ? value : undefined;
const validExecutionId = (value) =>
  typeof value === 'string' && /^\d{1,20}$/.test(value) ? value : undefined;
const validRequestId = (value) =>
  typeof value === 'string' && /^[A-Za-z0-9_-]{1,128}$/.test(value) ? value : undefined;
const knownCodes = new Set(['UPSTREAM_TIMEOUT', 'UPSTREAM_UNAVAILABLE', 'AUTHORIZATION_DENIED', 'INVALID_REQUEST']);

const classification = event.trigger ? 'TRIGGER_FAILURE' : 'EXECUTION_FAILURE';
const record = {
  status: 'error',
  type: 'shark_ai.workflow_failure',
  code: knownCodes.has(event.code) ? event.code : classification,
  timestamp: new Date().toISOString(),
  workflow_id: validWorkflowId(event.workflow?.id),
  execution_id: validExecutionId(event.execution?.id),
  retry_of: validExecutionId(event.execution?.retryOf),
  request_id: validRequestId(event.request_id),
  replay: 'manual_review_required',
  alert_delivery: 'unconfigured',
};

return { json: Object.fromEntries(Object.entries(record).filter(([, value]) => value !== undefined)) };
